import com.usamis.util.DatabaseConnection; import java.sql.*; public class SmokePurge { public static void main(String[] a) throws Exception { try (Connection c = DatabaseConnection.getConnection(); PreparedStatement ps = c.prepareStatement("DELETE FROM students WHERE id = ?")) { ps.setInt(1, Integer.parseInt(a[0])); int n = ps.executeUpdate(); System.out.println("purged=" + n); } } }
